129	/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
130	export async function listTakenOrgSlugs(
131	  prefix: string,
132	): Promise<readonly string[]> {
133	  const rows = getDb()
134	    .select({ slug: organizations.slug })
135	    .from(organizations)
136	    .where(like(organizations.slug, `${prefix}%`))
137	    .all();
138	  return rows.map((row) => row.slug);
139	}

